function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
var POOL = {
  '早餐':['燕麦粥配蓝莓','全麦吐司煎蛋','希腊酸奶配坚果','蔬菜蛋饼','红薯牛奶杯'],
  '午餐':['糙米饭配鸡胸与时蔬','藜麦牛油果沙拉','番茄虾仁意面','照烧豆腐盖饭','清蒸鱼配西兰花'],
  '晚餐':['蒜香烤蔬菜','味噌汤豆腐','烤三文鱼配芦笋','鸡丝凉面','南瓜浓汤配全麦'],
  '加餐':['苹果配杏仁','水煮蛋','无糖酸奶','胡萝卜条配鹰嘴豆泥','混合坚果一小把']
};
function mealsOf(n){ n=parseInt(n,10)||3; if(n===3) return ['早餐','午餐','晚餐']; if(n===4) return ['早餐','午餐','晚餐','加餐']; return ['早餐','上午加餐','午餐','下午加餐','晚餐']; }
function buildPlan(o){
  o=o||{};
  var goal=String(o.goal||'维持').trim()||'维持';
  var kcal=parseInt(o.kcal,10)||2000; if(kcal<800)kcal=800; if(kcal>5000)kcal=5000;
  var meals=mealsOf(o.meals);
  var days=parseInt(o.days,10)||7; if(days<1)days=1; if(days>14)days=14;
  var pref=String(o.pref||'').trim();
  var plan=[];
  for(var d=0; d<days; d++){
    var row=[];
    for(var mi=0; mi<meals.length; mi++){
      var pool=POOL[meals[mi]]||POOL['早餐'];
      row.push(pool[(d+mi)%pool.length]);
    }
    plan.push(row);
  }
  var head=['# 一周膳食计划：'+goal+'（目标 '+kcal+' kcal/天 · '+meals.length+' 餐）',''];
  var sep=meals.map(function(){return '------';}).join('|');
  head.push('| 天 | '+meals.join(' | ')+' |');
  head.push('|----|'+sep+'|');
  var wd=['周一','周二','周三','周四','周五','周六','周日'];
  for(var d2=0; d2<days; d2++){
    head.push('| '+wd[d2%7]+' | '+plan[d2].join(' | ')+' |');
  }
  if(pref) head.push('','> 饮食注意：'+pref);
  return {title:goal+'膳食计划', dayCount:days, mealCount:meals.length, markdown:head.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildPlan:buildPlan, mealsOf:mealsOf};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MealPlanForgePure = EXPORTS; }
